<?php
use App\Http\Controllers\Api\V1\Warehouse\Purchasing\WarehousePurchasingFinanceController as C; use App\Http\Middleware\ResolveWarehouseScope; use Illuminate\Support\Facades\Route;
Route::middleware(['api','auth:sanctum',ResolveWarehouseScope::class])->group(function(){
 Route::post('api/v1/warehouse/stock-ins/{id}/approve',[C::class,'approveStockIn'])->middleware('permission_or_snapshot:warehouse.stock_in.approve,warehouse.stock_in.update');
 Route::prefix('api/v1/warehouse/purchasing-finance')->group(function(){Route::get('/dashboard',[C::class,'dashboard'])->middleware('permission_or_snapshot:warehouse.purchasing.finance.view');Route::get('/supplier-invoices',[C::class,'invoices'])->middleware('permission_or_snapshot:warehouse.purchasing.invoice.view');Route::post('/stock-ins/{stockInId}/invoice',[C::class,'generate'])->middleware('permission_or_snapshot:warehouse.purchasing.invoice.create');Route::post('/supplier-invoices/{id}/landed-costs',[C::class,'landed'])->middleware('permission_or_snapshot:warehouse.purchasing.landed_cost.create');Route::get('/supplier-payments',[C::class,'payments'])->middleware('permission_or_snapshot:warehouse.purchasing.payment.view');Route::post('/supplier-payments',[C::class,'pay'])->middleware('permission_or_snapshot:warehouse.purchasing.payment.create');Route::post('/supplier-payments/{id}/void',[C::class,'voidPayment'])->middleware('permission_or_snapshot:warehouse.purchasing.payment.void');});});
